"""Supervisor entry point: persistent /data, authenticated Ingress only, optional scoped sensors, no bank sync."""
from __future__ import annotations

import json
import os
from pathlib import Path
import threading
import time


def main() -> None:
    options_file = Path("/data/options.json")
    options = json.loads(options_file.read_text()) if options_file.exists() else {}
    os.environ.update(RUNWAY_DATA="/data", RUNWAY_HA_INGRESS="1", RUNWAY_MANUAL_ONLY="1", RUNWAY_NO_SYNC="1")
    # A local key is generated by Runway on first start and retained in /data/secret.key (included in backups).
    os.environ["TZ"] = options.get("timezone", "America/New_York")
    if hasattr(time, "tzset"):
        time.tzset()
    token = options.get("sensor_token", "")
    if token and (not isinstance(token, str) or len(token) < 32):
        raise SystemExit("Sensor token must have at least 32 characters; generate a random token locally")
    if token:
        os.environ["RUNWAY_HA_SENSOR_TOKEN"] = token
    # Supervisor's data volume starts owned by root. Only named application files change owner, never arbitrary paths.
    if os.getuid() == 0:
        os.chown("/data", 1000, 1000)
        for name in ("runway.db", "runway.db-wal", "runway.db-shm", "secret.key"):
            path = Path("/data") / name
            if path.exists() and not path.is_symlink():
                os.chown(path, 1000, 1000)
        os.setgroups([])
        os.setgid(1000)
        os.setuid(1000)
    from ..storage import db
    from .handler import SensorHandler, Server, serve
    db.init()
    if token:
        server = Server(("0.0.0.0", 8766), SensorHandler)
        threading.Thread(target=server.serve_forever, daemon=True).start()
    serve(host="0.0.0.0", port=8765, auto_sync=False)


if __name__ == "__main__":
    main()
